//! Parametric equaliser: seven bands plus a frequency-response readout.
//!
//! PLAN §1.3 requires "参数均衡器（≥ 7 段，含频谱显示）". This module provides
//! the seven bands and the response computation the display needs;
//! [`super::spectrum`] provides the analysis.
//!
//! # Why seven bands are generated rather than written out
//!
//! Every band is the same biquad with different coefficients, so the parameter
//! table is built by a loop over [`BAND_COUNT`] rather than by 28 hand-written
//! descriptors. That is what keeps "band 4's frequency" and "band 4's type" in
//! step: they are generated by the same index.
//!
//! # Band layout
//!
//! Band 0 is a low shelf, band 6 a high shelf, and bands 1..=5 are peaking.
//! That is the layout every parametric EQ uses, and it means a user who only
//! touches the outer two knobs gets a tone control rather than a comb.
//!
//! # Real-time safety
//!
//! All seven biquads are inline in the struct and all scratch is allocated in
//! `prepare`. `process` performs no allocation.

use super::super::buffer::{AudioBuffer, RenderContext};
use super::super::{
    clamp_parameter, sanitize_wet, EffectCategory, EffectDescriptor, EffectProcessor,
};
use super::super::filter::biquad::{Biquad, FilterMode};
use crate::automation::parameter::{
    parameter_flags, ParameterAddress, ParameterDescriptor, ParameterUnit,
};

/// Number of bands. PLAN §1.3 requires at least seven.
pub const BAND_COUNT: usize = 7;

/// Parameters per band: enabled, type, frequency, gain, Q.
pub const PARAMS_PER_BAND: u16 = 5;

/// First band's `enabled` ordinal.
pub const PARAM_BAND_BASE: u16 = 0;
/// Output trim in decibels.
pub const PARAM_OUTPUT_DB: u16 = PARAM_BAND_BASE + PARAMS_PER_BAND * BAND_COUNT as u16;
/// Wet/dry in percent.
pub const PARAM_MIX: u16 = PARAM_OUTPUT_DB + 1;

/// Total published parameters.
pub const PARAM_COUNT: u16 = PARAM_MIX + 1;

/// Maximum channels the per-channel state covers.
const MAX_CHANNELS: usize = 2;

/// The effect's static description.
pub static DESCRIPTOR: EffectDescriptor = EffectDescriptor {
    kind: super::super::registry::KIND_EQ_PARAMETRIC,
    key: "parametric_eq",
    label: "Parametric EQ",
    category: EffectCategory::Equalizer,
    first_param: 0,
    param_count: PARAM_COUNT,
    has_latency: false,
    is_analysis_only: false,
};

/// The default filter type for band `index`.
///
/// The outer bands are shelves and the inner ones peaking, which is the layout
/// that makes the two end knobs useful on their own.
#[must_use]
pub const fn default_mode_for_band(index: usize) -> FilterMode {
    if index == 0 {
        FilterMode::LowShelf
    } else if index + 1 == BAND_COUNT {
        FilterMode::HighShelf
    } else {
        FilterMode::Peaking
    }
}

/// The default centre frequency for band `index`, in hertz.
///
/// Spread logarithmically from 80 Hz to 12 kHz so the seven bands cover the
/// audible range evenly rather than bunching at the bottom.
#[must_use]
pub fn default_frequency_for_band(index: usize) -> f32 {
    const LOW: f32 = 80.0;
    const HIGH: f32 = 12_000.0;
    if BAND_COUNT <= 1 {
        return LOW;
    }
    let t = index as f32 / (BAND_COUNT - 1) as f32;
    // Geometric interpolation, expressed through the shared `powf` so the
    // module needs no `std` math.
    LOW * super::super::util::dsp::powf(HIGH / LOW, t)
}

/// The default Q for band `index`.
#[must_use]
pub const fn default_q_for_band(index: usize) -> f32 {
    if index == 0 || index + 1 == BAND_COUNT {
        // Shelves use a gentler slope so they behave like tone controls.
        0.707
    } else {
        1.0
    }
}

/// The ordinal of the `field`-th parameter of `band`.
///
/// `field` 0..4 is enabled / type / frequency / gain / Q.
#[must_use]
pub const fn band_ordinal(band: usize, field: u16) -> u16 {
    PARAM_BAND_BASE + band as u16 * PARAMS_PER_BAND + field
}

/// Builds the full parameter table for an instance at `address`.
#[must_use]
pub fn parameter_table(address: ParameterAddress) -> [ParameterDescriptor; PARAM_COUNT as usize] {
    let slot = address.effect_slot();
    let channel = address.index;
    let at = |sub: u16| ParameterAddress::effect(channel, slot, sub);

    // Build with a fixed-size array and index assignment rather than a Vec, so
    // the table stays a plain array the engine can hold inline.
    let mut table = [ParameterDescriptor {
        address: at(0),
        key: "",
        label: "",
        unit: ParameterUnit::Linear,
        flags: 0,
        min_value: 0.0,
        max_value: 1.0,
        default_value: 0.0,
        smoothing_ms: 0.0,
    }; PARAM_COUNT as usize];

    let mut band = 0;
    while band < BAND_COUNT {
        let default_mode = default_mode_for_band(band);
        // A band is enabled by default only if it is not a do-nothing peaking
        // band at 0 dB. Bands 1/2/3/4/5 start enabled so a user can grab one
        // immediately; the 0 dB default means they are transparent until moved.
        table[band_ordinal(band, 0) as usize] = ParameterDescriptor {
            address: at(band_ordinal(band, 0)),
            key: BAND_ENABLED_KEYS[band],
            label: BAND_ENABLED_LABELS[band],
            unit: ParameterUnit::Enumeration,
            flags: parameter_flags::DISCRETE,
            min_value: 0.0,
            max_value: 1.0,
            default_value: 1.0,
            smoothing_ms: 0.0,
        };
        table[band_ordinal(band, 1) as usize] = ParameterDescriptor {
            address: at(band_ordinal(band, 1)),
            key: BAND_TYPE_KEYS[band],
            label: BAND_TYPE_LABELS[band],
            unit: ParameterUnit::Enumeration,
            flags: parameter_flags::DISCRETE,
            min_value: 0.0,
            max_value: 7.0,
            default_value: default_mode.as_u32() as f32,
            smoothing_ms: 0.0,
        };
        table[band_ordinal(band, 2) as usize] = ParameterDescriptor {
            address: at(band_ordinal(band, 2)),
            key: BAND_FREQ_KEYS[band],
            label: BAND_FREQ_LABELS[band],
            unit: ParameterUnit::Hertz,
            flags: parameter_flags::AUTOMATABLE
                | parameter_flags::LOGARITHMIC
                | parameter_flags::SMOOTHED,
            min_value: 20.0,
            max_value: 20_000.0,
            default_value: default_frequency_for_band(band),
            smoothing_ms: 15.0,
        };
        table[band_ordinal(band, 3) as usize] = ParameterDescriptor {
            address: at(band_ordinal(band, 3)),
            key: BAND_GAIN_KEYS[band],
            label: BAND_GAIN_LABELS[band],
            unit: ParameterUnit::Decibels,
            flags: parameter_flags::AUTOMATABLE
                | parameter_flags::BIPOLAR
                | parameter_flags::SMOOTHED,
            min_value: -24.0,
            max_value: 24.0,
            default_value: 0.0,
            smoothing_ms: 15.0,
        };
        table[band_ordinal(band, 4) as usize] = ParameterDescriptor {
            address: at(band_ordinal(band, 4)),
            key: BAND_Q_KEYS[band],
            label: BAND_Q_LABELS[band],
            unit: ParameterUnit::Linear,
            flags: parameter_flags::AUTOMATABLE | parameter_flags::SMOOTHED,
            min_value: 0.1,
            max_value: 18.0,
            default_value: default_q_for_band(band),
            smoothing_ms: 15.0,
        };
        band += 1;
    }

    table[PARAM_OUTPUT_DB as usize] = ParameterDescriptor {
        address: at(PARAM_OUTPUT_DB),
        key: "output_db",
        label: "Output",
        unit: ParameterUnit::Decibels,
        flags: parameter_flags::AUTOMATABLE | parameter_flags::BIPOLAR | parameter_flags::SMOOTHED,
        min_value: -24.0,
        max_value: 24.0,
        default_value: 0.0,
        smoothing_ms: 10.0,
    };
    table[PARAM_MIX as usize] = ParameterDescriptor {
        address: at(PARAM_MIX),
        key: "mix",
        label: "Mix",
        unit: ParameterUnit::Percent,
        flags: parameter_flags::AUTOMATABLE | parameter_flags::SMOOTHED,
        min_value: 0.0,
        max_value: 100.0,
        default_value: 100.0,
        smoothing_ms: 10.0,
    };
    table
}

